1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireArea } from "@/lib/rbac";
4	import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
5	import { FeedbackRowControls } from "@/components/admin/FeedbackControls";
6	
7	export const dynamic = "force-dynamic";
8	
9	const KINDS = ["BUG", "FEATURE"] as const;
10	const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;
11	
12	const statusTone: Record<string, "slate" | "brand" | "amber" | "green" | "red"> = {
13	  NEW: "slate",
14	  PLANNED: "brand",
15	  IN_PROGRESS: "amber",
16	  DONE: "green",
17	  DECLINED: "red",
18	};
19	
20	function filterHref(kind: string | undefined, status: string | undefined): string {
21	  const p = new URLSearchParams();
22	  if (kind) p.set("kind", kind);
23	  if (status) p.set("status", status);
24	  const q = p.toString();
25	  return q ? `/admin/feedback?${q}` : "/admin/feedback";
26	}
27	
28	function Pill({
29	  active,
30	  href,
31	  children,
32	}: {
33	  active: boolean;
34	  href: string;
35	  children: React.ReactNode;
36	}) {
37	  return (
38	    <Link
39	      href={href}
40	      className={
41	        active
42	          ? "rounded-full border border-brand-500/50 bg-brand-500/15 px-3 py-1 text-xs font-medium text-brand-200"
43	          : "rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-xs font-medium text-slate-400 hover:text-slate-200"
44	      }
45	    >
46	      {children}
47	    </Link>
48	  );
49	}
50	
51	export default async function AdminFeedbackPage({
52	  searchParams,
53	}: {
54	  searchParams: Promise<{ kind?: string; status?: string }>;
55	}) {
56	  await requireArea("support");
57	  const sp = await searchParams;
58	
59	  const kind = (KINDS as readonly string[]).includes(sp.kind ?? "") ? sp.kind : undefined;
60	  const status = (STATUSES as readonly string[]).includes(sp.status ?? "") ? sp.status : undefined;
61	
62	  const where: { kind?: string; status?: string } = {};
63	  if (kind) where.kind = kind;
64	  if (status) where.status = status;
65	
66	  const items = await db.feedback.findMany({
67	    where,
68	    include: { user: { select: { email: true, name: true } } },
69	    orderBy: { createdAt: "desc" },
70	  });
71	
72	  const openCount = await db.feedback.count({ where: { status: { in: ["NEW", "PLANNED", "IN_PROGRESS"] } } });
73	
74	  return (
75	    <div className="space-y-6">
76	      <PageHeader
77	        title="Feedback"
78	        sub={`Bug reports and feature requests from customers. ${openCount} open.`}
79	      />
80	
81	      <div className="card space-y-3">
82	        <div className="flex flex-wrap items-center gap-2">
83	          <span className="mr-1 text-xs font-medium text-slate-500">Type</span>
84	          <Pill active={!kind} href={filterHref(undefined, status)}>
85	            All
86	          </Pill>
87	          {KINDS.map((k) => (
88	            <Pill key={k} active={kind === k} href={filterHref(k, status)}>
89	              {k === "BUG" ? "Bugs" : "Features"}
90	            </Pill>
91	          ))}
92	        </div>
93	        <div className="flex flex-wrap items-center gap-2">
94	          <span className="mr-1 text-xs font-medium text-slate-500">Status</span>
95	          <Pill active={!status} href={filterHref(kind, undefined)}>
96	            All
97	          </Pill>
98	          {STATUSES.map((s) => (
99	            <Pill key={s} active={status === s} href={filterHref(kind, s)}>
100	              {s.replace(/_/g, " ").toLowerCase()}
101	            </Pill>
102	          ))}
103	        </div>
104	      </div>
105	
106	      {items.length === 0 ? (
107	        <EmptyState
108	          title="No feedback matches"
109	          sub="Nothing here for the current filter. Try widening it."
110	        />
111	      ) : (
112	        <div className="card overflow-x-auto p-0">
113	          <table className="table-shell min-w-[900px]">
114	            <thead>
115	              <tr>
116	                <th>Type</th>
117	                <th>Details</th>
118	                <th>From</th>
119	                <th>Status</th>
120	                <th>Triage</th>
121	                <th className="text-right">Submitted</th>
122	              </tr>
123	            </thead>
124	            <tbody>
125	              {items.map((f) => (
126	                <tr key={f.id}>
127	                  <td>
128	                    <Badge tone={f.kind === "BUG" ? "red" : "brand"}>
129	                      {f.kind === "BUG" ? "bug" : "feature"}
130	                    </Badge>
131	                  </td>
132	                  <td className="max-w-sm">
133	                    <div className="font-semibold text-slate-100">{f.title}</div>
134	                    <div className="mt-0.5 whitespace-pre-wrap text-xs text-slate-400">{f.body}</div>
135	                    {f.url && (
136	                      <div className="mt-1 font-mono text-[11px] text-slate-500">on {f.url}</div>
137	                    )}
138	                  </td>
139	                  <td className="text-xs text-slate-400">
140	                    {f.user ? (
141	                      <>
142	                        <div className="text-slate-300">{f.user.name}</div>
143	                        <div>{f.user.email}</div>
144	                      </>
145	                    ) : (
146	                      <span className="text-slate-500">deleted user</span>
147	                    )}
148	                  </td>
149	                  <td>
150	                    <Badge tone={statusTone[f.status] ?? "slate"}>
151	                      {f.status.replace(/_/g, " ").toLowerCase()}
152	                    </Badge>
153	                  </td>
154	                  <td>
155	                    <FeedbackRowControls id={f.id} status={f.status} adminNote={f.adminNote} />
156	                  </td>
157	                  <td className="text-right text-xs text-slate-400">{timeAgo(f.createdAt)}</td>
158	                </tr>
159	              ))}
160	            </tbody>
161	          </table>
162	        </div>
163	      )}
164	    </div>
165	  );
166	}
