1	"use client";
2	
3	import {
4	  useCallback,
5	  useEffect,
6	  useRef,
7	  useState,
8	  useTransition,
9	  type ClipboardEvent,
10	} from "react";
11	import {
12	  listConversations,
13	  replyToConversation,
14	  replyWithAttachment,
15	  closeConversation,
16	  assignConversation,
17	} from "@/lib/actions-chat";
18	
19	/**
20	 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
21	 * first) and a thread view with a reply box. Polls `listConversations` every
22	 * few seconds so new visitor messages appear without a manual refresh.
23	 */
24	
25	type Attachment = { id: string; mime: string; sizeBytes: number };
26	type Msg = {
27	  id: string;
28	  sender: string;
29	  body: string;
30	  createdAt: string;
31	  attachment?: Attachment | null;
32	};
33	type Convo = {
34	  id: string;
35	  visitorId: string;
36	  userId: string | null;
37	  name: string | null;
38	  email: string | null;
39	  status: string;
40	  assignedToId: string | null;
41	  unreadForAgent: boolean;
42	  lastMessageAt: string;
43	  createdAt: string;
44	  messages: Msg[];
45	};
46	
47	const POLL_MS = 5000;
48	
49	// Client-side pre-checks only; replyWithAttachment re-validates by signature.
50	const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
51	const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
52	const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
53	
54	function imageError(file: File): string | null {
55	  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
56	  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
57	  return null;
58	}
59	
60	function timeAgo(iso: string): string {
61	  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
62	  if (s < 60) return `${s}s ago`;
63	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
64	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
65	  return `${Math.floor(s / 86400)}d ago`;
66	}
67	
68	export default function ChatInbox({ initial }: { initial: Convo[] }) {
69	  const [convos, setConvos] = useState<Convo[]>(initial);
70	  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
71	  const [draft, setDraft] = useState("");
72	  const [error, setError] = useState("");
73	  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
74	  const [pending, start] = useTransition();
75	  const scrollRef = useRef<HTMLDivElement>(null);
76	  const fileInputRef = useRef<HTMLInputElement>(null);
77	
