5	
6	const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;
7	
8	/**
9	 * Per-row triage control: a status dropdown + an internal admin note that saves
10	 * together. Both persist via `adminUpdateFeedback`.
11	 */
12	export function FeedbackRowControls({
13	  id,
14	  status,
15	  adminNote,
16	}: {
17	  id: string;
18	  status: string;
19	  adminNote: string | null;
20	}) {
21	  const [nextStatus, setNextStatus] = useState(status);
22	  const [note, setNote] = useState(adminNote ?? "");
23	  const [pending, start] = useTransition();
24	  const [msg, setMsg] = useState<{ error?: string; ok?: boolean }>({});
25	
26	  const dirty = nextStatus !== status || note !== (adminNote ?? "");
27	
28	  function save() {
29	    setMsg({});
30	    start(async () => {
31	      const res = await adminUpdateFeedback(id, nextStatus, note);
32	      setMsg(res ?? {});
33	    });
34	  }
35	
36	  return (
37	    <div className="flex min-w-[240px] flex-col gap-2">
38	      <select
39	        className="input w-full py-1.5 text-xs"
40	        value={nextStatus}
41	        onChange={(e) => setNextStatus(e.target.value)}
42	        disabled={pending}
43	      >
44	        {STATUSES.map((s) => (
45	          <option key={s} value={s}>
46	            {s.replace(/_/g, " ").toLowerCase()}
47	          </option>
48	        ))}
49	      </select>
50	      <textarea
51	        className="input min-h-16 w-full resize-y py-1.5 text-xs"
52	        value={note}
53	        onChange={(e) => setNote(e.target.value)}
54	        placeholder="Internal note (shown to reporter)…"
55	        maxLength={2000}
56	        disabled={pending}
57	      />
58	      <div className="flex items-center gap-2">
59	        <button
60	          className="btn-primary py-1 text-xs"
61	          disabled={pending || !dirty}
62	          onClick={save}
63	        >
64	          {pending ? "Saving…" : "Save"}
65	        </button>
66	        {msg.ok && !dirty && <span className="text-xs text-emerald-400">Saved</span>}
67	        {msg.error && <span className="text-xs text-red-400">{msg.error}</span>}
68	      </div>
69	    </div>
70	  );
71	}
