19	/**
20	 * Byte-identical copy of `bodyToHtml` in lib/actions-newsletter-campaign.ts,
21	 * used to render the live preview client-side. Keep the two in sync.
22	 */
23	function bodyToHtml(body: string): string {
24	  const src = body.trim();
25	  if (!src) return "";
26	
27	  if (/<(p|div|table|h[1-6]|ul|ol|li|img|br|a|span|section|center|strong|em|blockquote)\b/i.test(src)) {
28	    return src;
29	  }
30	
31	  const inline = (t: string) =>
32	    t
33	      .replace(
34	        /\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g,
35	        '<a href="$2" style="color:#8a70fb;text-decoration:none">$1</a>',
36	      )
37	      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
38	      .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>")
39	      .replace(
40	        /`([^`]+)`/g,
41	        '<code style="background:#0a101f;padding:2px 5px;border-radius:5px">$1</code>',
42	      );
43	
44	  const lines = src.split(/\r?\n/);
45	  const out: string[] = [];
46	  let list: string[] = [];
47	  let para: string[] = [];
48	
49	  const flushList = () => {
50	    if (list.length) {
51	      out.push(
52	        `<ul style="margin:12px 0;padding-left:20px">${list
53	          .map((li) => `<li style="margin:4px 0">${inline(li)}</li>`)
54	          .join("")}</ul>`,
55	      );
56	      list = [];
57	    }
58	  };
59	  const flushPara = () => {
60	    if (para.length) {
61	      out.push(`<p style="margin:0 0 14px">${inline(para.join(" "))}</p>`);
62	      para = [];
63	    }
64	  };
65	
66	  for (const raw of lines) {
67	    const line = raw.trim();
68	    if (!line) {
69	      flushList();
70	      flushPara();
71	      continue;
72	    }
73	    const h = /^(#{1,3})\s+(.*)$/.exec(line);
74	    if (h) {
75	      flushList();
76	      flushPara();
77	      const level = h[1].length;
78	      const size = level === 1 ? 22 : level === 2 ? 18 : 15;
79	      out.push(
80	        `<h${level} style="margin:18px 0 10px;font-size:${size}px;color:#ffffff">${inline(h[2])}</h${level}>`,
81	      );
82	      continue;
83	    }
84	    if (/^[-*]\s+/.test(line)) {
85	      flushPara();
86	      list.push(line.replace(/^[-*]\s+/, ""));
87	      continue;
88	    }
89	    flushList();
90	    para.push(line);
91	  }
92	  flushList();
93	  flushPara();
94	  return out.join("\n");
95	}
