200	/** Per-row Edit / Send / Delete controls for the campaigns table. */
201	export function CampaignRowActions({
202	  id,
203	  subject,
204	  status,
205	  subscriberCount,
206	}: {
207	  id: string;
208	  subject: string;
209	  status: string;
210	  subscriberCount: number;
211	}) {
212	  const [pending, start] = useTransition();
213	  const [confirming, setConfirming] = useState(false);
214	  const [msg, setMsg] = useState<string | null>(null);
215	  const [err, setErr] = useState<string | null>(null);
216	
217	  const locked = status === "SENDING" || status === "SENT";
218	
219	  const doSend = () => {
220	    if (subscriberCount === 0) {
221	      setErr("There are no subscribers to send to yet.");
222	      return;
223	    }
224	    const ok = window.confirm(
225	      `Send "${subject}" to ${subscriberCount} subscriber${subscriberCount === 1 ? "" : "s"}?\n\nThis cannot be undone.`,
226	    );
227	    if (!ok) return;
228	    start(async () => {
229	      setErr(null);
230	      setMsg(null);
231	      const res = await sendCampaign(id);
232	      if (res.error) setErr(res.error);
233	      else setMsg(`Sent to ${res.sent} subscriber${res.sent === 1 ? "" : "s"}.`);
234	    });
235	  };
236	
237	  return (
238	    <div className="flex flex-wrap items-center justify-end gap-2">
239	      {err && <span className="text-xs text-red-400">{err}</span>}
240	      {msg && <span className="text-xs text-emerald-400">{msg}</span>}
241	
242	      {!locked && (
243	        <Link href={`/admin/newsletter?edit=${id}`} className="btn-secondary px-3 py-1.5 text-xs">
244	          Edit
245	        </Link>
246	      )}
247	
248	      {!locked && (
249	        <button className="btn-primary px-3 py-1.5 text-xs" disabled={pending} onClick={doSend}>
250	          {pending ? "Sending…" : "Send"}
251	        </button>
252	      )}
253	
254	      {confirming ? (
255	        <>
256	          <button
257	            className="btn-danger px-3 py-1.5 text-xs"
258	            disabled={pending}
259	            onClick={() =>
260	              start(async () => {
261	                setErr(null);
262	                const res = await deleteCampaign(id);
263	                if (res.error) {
264	                  setErr(res.error);
265	                  setConfirming(false);
266	                }
267	              })
268	            }
269	          >
270	            {pending ? "Deleting…" : "Confirm"}
271	          </button>
272	          <button
273	            className="btn-ghost px-2 py-1.5 text-xs"
274	            disabled={pending}
275	            onClick={() => setConfirming(false)}
276	          >
277	            Cancel
278	          </button>
279	        </>
280	      ) : (
281	        status !== "SENDING" && (
282	          <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
283	            Delete
284	          </button>
285	        )
286	      )}
287	    </div>
288	  );
289	}
