22	 *   - `setTicketStatus` and `replyTicket` applied the CUSTOMER ownership test
23	 *     (`ticket.userId !== user.id && role !== "ADMIN"`), so a SUPPORT agent could
24	 *     neither close nor answer a ticket that was not their own — i.e. any ticket.
25	 *
26	 * So the entire job of the SUPPORT role was a read-only page with three controls
27	 * that silently refused. `lib/actions-chat.ts` — the other half of the same area —
28	 * has always gated correctly on `requireArea("support")`; the ticket desk simply
29	 * was never updated when RBAC landed. These now use the same rule. No role gains
30	 * anything `lib/rbac.ts` did not already declare, and CUSTOMER is unaffected:
31	 * a customer still reaches only their own ticket.
32	 */
33	/**
34	 * The session behind a ticket action, plus whether they are support staff.
35	 *
36	 * Named `require*` deliberately. `test/auth-lockouts.test.ts` enforces that every
37	 * export of a "use server" file — each of which is a network-callable endpoint
38	 * anyone can POST to — calls a recognised guard INSIDE the function, and it
39	 * recognises guards by the `require*`/`owned*`/`assert*`/`resolve*` convention.
40	 * This helper was `ticketActor`, which guarded correctly but did not LOOK like a
41	 * guard, so the tripwire reported three genuinely-safe endpoints as unguarded.
42	 *
43	 * The fix was the name, not the rule: widening the rule to accept arbitrary
44	 * helper names would let a future function that guards nothing pass the same
45	 * check. A guard should be recognisable as one.
46	 */
47	async function requireTicketActor(): Promise<{ id: string; isSupportStaff: boolean }> {
48	  const user = await requireUser();
49	  return { id: user.id, isSupportStaff: canAccess(user.role, "support") };
50	}
51	
52	export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
53	  const user = await requireUser();
54	  const parsed = z
55	    .object({
56	      subject: z.string().min(3).max(150),
57	      body: z.string().min(5).max(10000),
58	      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
59	    })
60	    .safeParse({
61	      subject: formData.get("subject"),
62	      body: formData.get("body"),
63	      priority: formData.get("priority") ?? "NORMAL",
64	    });
65	  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };
66	
67	  const ticket = await db.ticket.create({
68	    data: {
69	      subject: parsed.data.subject,
70	      priority: parsed.data.priority,
71	      userId: user.id,
72	      messages: { create: { body: parsed.data.body, authorId: user.id, isStaff: false } },
73	    },
74	  });
75	  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
76	  await db.notification.createMany({
77	    data: admins.map((a) => ({
78	      userId: a.id,
79	      title: `New ticket: ${parsed.data.subject}`,
80	      href: `/admin/support/${ticket.id}`,
81	    })),
82	  });
83	  redirect(`/dashboard/support/${ticket.id}`);
84	}
85	
86	export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
87	  const user = await requireTicketActor();
88	  const ticketId = String(formData.get("ticketId") ?? "");
89	  const body = String(formData.get("body") ?? "").trim();
90	  if (body.length < 2 || body.length > 10000) return { error: "Message too short." };
91	
92	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
93	  if (!ticket) return { error: "Ticket not found." };
94	  const isStaff = user.isSupportStaff && ticket.userId !== user.id;
95	  if (ticket.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };
96	
97	  await db.$transaction([
98	    db.ticketMessage.create({ data: { ticketId, body, authorId: user.id, isStaff } }),
99	    db.ticket.update({
100	      where: { id: ticketId },
101	      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
102	    }),
103	  ]);
104	
105	  if (isStaff) {
106	    await db.notification.create({
107	      data: {
108	        userId: ticket.userId,
109	        title: `Support replied: ${ticket.subject}`,
110	        href: `/dashboard/support/${ticketId}`,
111	      },
112	    });
113	  } else {
114	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
115	    await db.notification.createMany({
116	      data: admins.map((a) => ({
117	        userId: a.id,
118	        title: `Ticket reply: ${ticket.subject}`,
119	        href: `/admin/support/${ticketId}`,
120	      })),
121	    });
122	  }
123	  revalidatePath(`/dashboard/support/${ticketId}`);
124	  revalidatePath(`/admin/support/${ticketId}`);
125	  return {};
126	}
127	
128	/**
129	 * A TypeScript parameter type is a compile-time comment on a network endpoint.
130	 *
131	 * Every export of this file is POST-able with any JSON the caller likes, so the
132	 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
133	 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
134	 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
135	 * the support queue's "needs a reply" view without anyone having replied. Values
136	 * outside the enum reached Prisma and threw, which surfaces as a server error
137	 * page rather than a message. Both are fixed by validating at the boundary.
138	 */
139	const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
140	const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;
141	
142	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
143	  const user = await requireTicketActor();
144	  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
145	    throw new Error("A ticket can only be reopened or closed from here.");
146	  }
147	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
148	  if (!ticket) throw new Error("Not found");
149	  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
150	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
151	  revalidatePath(`/dashboard/support`);
152	  revalidatePath(`/dashboard/support/${ticketId}`);
153	  revalidatePath(`/admin/support`);
154	  revalidatePath(`/admin/support/${ticketId}`);
155	}
156	
157	export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
158	  const user = await requireTicketActor();
159	  // Triage is a staff-only judgement — a customer must not be able to promote
160	  // their own ticket to URGENT — but it IS the support desk's job.
161	  if (!user.isSupportStaff) throw new Error("Forbidden");
162	  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
163	    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
164	  }
165	  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
166	  revalidatePath(`/admin/support`);
167	  revalidatePath(`/admin/support/${ticketId}`);
168	}
