107	export async function replyToConversation(
108	  id: string,
109	  body: string
110	): Promise<{ error?: string; ok?: boolean }> {
111	  const staff = await requireArea("support");
112	
113	  const parsed = z
114	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
115	    .safeParse({ id, body });
