119	  if (!convo) return { error: "Conversation not found." };
120	
121	  await db.$transaction([
122	    db.chatMessage.create({
123	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
124	    }),
125	    db.chatConversation.update({
126	      where: { id: parsed.data.id },
127	      data: {
128	        status: "OPEN",
129	        unreadForUser: true,
130	        unreadForAgent: false,
131	        assignedToId: staff.id,
132	        lastMessageAt: new Date(),
133	      },
134	    }),
135	  ]);
