17	/**
18	 * Render an authored newsletter body to email-ready HTML.
19	 *
20	 * Non-exported (sync) so it lives happily inside a "use server" module. The
21	 * NewsletterComposer client keeps a byte-identical copy for its live preview —
22	 * keep the two in sync if you change the markdown subset here.
23	 *
24	 * If the author already wrote block-level HTML we pass it through untouched;
25	 * otherwise we render a small, safe markdown subset (headings, bold, italic,
26	 * inline code, links and bullet lists).
27	 */
28	function bodyToHtml(body: string): string {
29	  const src = body.trim();
30	  if (!src) return "";
31	
32	  if (/<(p|div|table|h[1-6]|ul|ol|li|img|br|a|span|section|center|strong|em|blockquote)\b/i.test(src)) {
33	    return src;
34	  }
35	
36	  const inline = (t: string) =>
37	    t
38	      .replace(
39	        /\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g,
40	        '<a href="$2" style="color:#8a70fb;text-decoration:none">$1</a>',
41	      )
42	      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
43	      .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>")
44	      .replace(
45	        /`([^`]+)`/g,
46	        '<code style="background:#0a101f;padding:2px 5px;border-radius:5px">$1</code>',
47	      );
48	
49	  const lines = src.split(/\r?\n/);
50	  const out: string[] = [];
51	  let list: string[] = [];
52	  let para: string[] = [];
53	
54	  const flushList = () => {
55	    if (list.length) {
56	      out.push(
57	        `<ul style="margin:12px 0;padding-left:20px">${list
58	          .map((li) => `<li style="margin:4px 0">${inline(li)}</li>`)
59	          .join("")}</ul>`,
60	      );
61	      list = [];
62	    }
63	  };
64	  const flushPara = () => {
65	    if (para.length) {
66	      out.push(`<p style="margin:0 0 14px">${inline(para.join(" "))}</p>`);
67	      para = [];
68	    }
69	  };
70	
71	  for (const raw of lines) {
72	    const line = raw.trim();
73	    if (!line) {
74	      flushList();
75	      flushPara();
76	      continue;
77	    }
78	    const h = /^(#{1,3})\s+(.*)$/.exec(line);
79	    if (h) {
80	      flushList();
81	      flushPara();
82	      const level = h[1].length;
83	      const size = level === 1 ? 22 : level === 2 ? 18 : 15;
84	      out.push(
85	        `<h${level} style="margin:18px 0 10px;font-size:${size}px;color:#ffffff">${inline(h[2])}</h${level}>`,
86	      );
87	      continue;
88	    }
89	    if (/^[-*]\s+/.test(line)) {
90	      flushPara();
91	      list.push(line.replace(/^[-*]\s+/, ""));
92	      continue;
93	    }
94	    flushList();
95	    para.push(line);
96	  }
97	  flushList();
98	  flushPara();
99	  return out.join("\n");
100	}
