175	/**
176	 * Send a campaign to every newsletter subscriber.
177	 *
178	 * Best-effort: marks the campaign SENDING, then walks the subscriber list one
179	 * message at a time via `sendMail` (which never throws and logs each attempt to
180	 * EmailLog). A failure to any single address is counted and skipped — it never
181	 * aborts the batch. A tiny per-message delay throttles the SMTP relay. On
182	 * completion the campaign is set SENT with the success count (or FAILED if not
183	 * a single message went out).
184	 */
185	export async function sendCampaign(id: string): Promise<{ error?: string; sent?: number }> {
186	  await requireArea("platform");
187	
188	  const campaign = await db.newsletterCampaign.findUnique({ where: { id } });
189	  if (!campaign) return { error: "Campaign not found." };
190	  if (campaign.status === "SENDING") return { error: "This campaign is already being sent." };
191	  if (campaign.status === "SENT") return { error: "This campaign has already been sent." };
192	
193	  const subscribers = await db.newsletterSubscriber.findMany({ select: { email: true } });
194	  if (subscribers.length === 0) return { error: "There are no subscribers to send to yet." };
195	
196	  await db.newsletterCampaign.update({ where: { id }, data: { status: "SENDING" } });
197	
198	  const html = wrapEmail(bodyToHtml(campaign.html));
199	  let sent = 0;
200	
201	  try {
202	    for (const sub of subscribers) {
203	      try {
204	        const ok = await sendMail({ to: sub.email, subject: campaign.subject, html });
205	        if (ok) sent++;
206	      } catch (e) {
207	        // sendMail is documented not to throw, but stay defensive so one bad
208	        // address can never abort the whole run.
209	        await logEvent("warn", "newsletter.campaign.recipient", {
210	          id,
211	          email: sub.email,
212	          message: String((e as Error)?.message ?? e),
213	        });
214	      }
215	      // Gentle throttle so we don't hammer the relay on larger lists.
216	      await new Promise((r) => setTimeout(r, 40));
217	    }
218	
219	    const status = sent > 0 ? "SENT" : "FAILED";
220	    await db.newsletterCampaign.update({
221	      where: { id },
222	      data: { status, sentCount: sent, sentAt: new Date() },
223	    });
224	    await logEvent("info", "newsletter.campaign.sent", {
225	      id,
226	      subject: campaign.subject,
227	      total: subscribers.length,
228	      sent,
229	    });
230	    revalidatePath("/admin/newsletter");
231	
232	    if (sent === 0) {
233	      return { error: "No emails could be sent — check the SMTP configuration in Settings.", sent: 0 };
234	    }
235	    return { sent };
236	  } catch (e) {
237	    await db.newsletterCampaign
238	      .update({ where: { id }, data: { status: "FAILED", sentCount: sent } })
239	      .catch(() => {});
240	    await logEvent("error", "newsletter.campaign.send", { id, message: String((e as Error)?.message ?? e) });
241	    revalidatePath("/admin/newsletter");
242	    return { error: "The send failed unexpectedly. Some messages may have gone out.", sent };
243	  }
244	}
