110	// ---------- Password reset (email-based) ----------
111	
112	export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
113	  // This lookup was ALREADY lowercasing while register/login stored the address
114	  // verbatim, which is precisely why a `Alice@Example.com` signup could never be
115	  // reset. Both sides now share one definition rather than two that agreed by
116	  // luck — see lib/email-normalize.ts.
117	  const email = normalizeEmail(formData.get("email"));
118	  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
119	  // and enumeration probing. On limit, still report success below (no leak).
120	  //
121	  // `clientIp` rather than the first `x-forwarded-for` entry, which is a field
122	  // the CALLER fills in (nginx appends the real address, it does not replace the
123	  // header). Keying on it let one script vary the fake value per request and get
124	  // a fresh 5-attempt allowance every time, which mattered twice over here: it
125	  // uncapped the reset-mail flood AND it removed the cap on the timing probe
126	  // below.
127	  const ip = clientIp(await headers());
128	  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
129	  if (!rl.ok) return { sent: true };
130	  // Always report success (don't leak which emails exist)
131	  const user = await db.user.findUnique({ where: { email } });
132	  if (user) {
133	    const { randomBytes, createHash } = await import("node:crypto");
134	    const token = randomBytes(32).toString("base64url");
135	    const tokenHash = createHash("sha256").update(token).digest("hex");
136	    await db.passwordResetToken.create({
137	      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
138	    });
139	    const { sendMail, emails } = await import("./mailer");
140	    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
141	    const tpl = emails.passwordReset(link);
142	    // THE SEND IS DELIBERATELY NOT AWAITED, and that is a security property, not
143	    // an optimisation.
144	    //
145	    // "If an account exists for that email, a reset link is on its way" is the
146	    // right answer and is returned either way — but only ONE of the two branches
147	    // used to open an SMTP conversation before answering. A known address took
148	    // as long as the mail server did; an unknown one returned after a single
149	    // indexed SELECT. The wording revealed nothing and the clock revealed
150	    // everything, one sample per address, which is a working account-enumeration
151	    // oracle against a hosting provider's whole customer list. Detaching the send
152	    // leaves the two branches differing by one INSERT.
153	    //
154	    // Nothing is lost by not waiting: the result was already discarded, and the
155	    // customer was never told whether it worked. Failures are logged, and the
156	    // rejection is swallowed so a dead mail server can never take the process
157	    // down through an unhandled rejection.
158	    //
159	    // `mayDeliverTo` consults the notification policy, which classifies
160	    // `password_reset` as CRITICAL and returns true without even loading the
161	    // preferences. The call is here so the POLICY decides, not this call site: a
162	    // reset link is the only route back into a locked-out account, so honouring
163	    // an "Account email: off" checkbox here would lock the customer out of their
164	    // own account permanently.
165	    void (async () => {
166	      if (await mayDeliverTo(user.id, "password_reset", "email")) {
167	        await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
168	      }
169	    })().catch((e) => {
170	      console.error("[password-reset] send failed:", e);
171	    });
172	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
173	  }
174	  return { sent: true };
175	}
176	
177	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
178	  const token = String(formData.get("token") ?? "");
179	  const password = String(formData.get("password") ?? "");
180	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
181	  const { createHash } = await import("node:crypto");
182	  const tokenHash = createHash("sha256").update(token).digest("hex");
183	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
184	  if (!row || row.usedAt || row.expiresAt < new Date()) {
185	    return { error: "This reset link is invalid or has expired. Request a new one." };
186	  }
187	  await db.$transaction([
188	    // Bump sessionVersion so any sessions predating the reset are evicted.
189	    db.user.update({
190	      where: { id: row.userId },
191	      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
192	    }),
193	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
194	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
195	  ]);
196	  return { ok: true };
197	}
