203	  if (!user) throw new Error("User not found");
204	  const { randomBytes, createHash } = await import("node:crypto");
205	  const token = randomBytes(32).toString("base64url");
206	  const tokenHash = createHash("sha256").update(token).digest("hex");
207	  await db.passwordResetToken.create({
208	    data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
209	  });
210	  const { sendMail, emails } = await import("./mailer");
211	  const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
212	  const tpl = emails.passwordReset(link);
213	  // CRITICAL (see above): support has just told the customer "check your email".
214	  // A preference must not be able to make that a lie.
215	  if (await mayDeliverTo(user.id, "password_reset", "email")) {
216	    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html });
217	  }
218	  await db.auditLog.create({ data: { userId: admin.id, action: "admin.password_reset_sent", detail: user.email } });
