327	/**
328	 * Bulk-suspend clients. ADMIN-only, matching the single-account path.
329	 *
330	 * REAL DEFECT (2026-07-27 admin audit). This gated on `requireArea("clients")`,
331	 * which admits SUPPORT — while `adminSetUserSuspended` in lib/actions.ts, the
332	 * per-row "Suspend" button rendered on the SAME page for the SAME operation,
333	 * calls `requireAdmin()`. So the two suspend paths disagreed, and it was the
334	 * BULK one that was looser: a SUPPORT agent could not suspend one customer but
335	 * could tick select-all and suspend 500 in a single click. Suspension logs the
336	 * account out (`realUser` refuses a suspended row) and blocks login, so that is
337	 * a whole-customer-base outage available to the lowest-privileged staff role.
338	 *
339	 * Aligned upward to the stricter of the two, because the stricter one is the
340	 * deliberate one: it also refuses self-suspension and records the reason.
341	 *
342	 * The acting admin is never suspended, and ADMIN accounts are excluded.
343	 */
344	export async function bulkSuspendUsers(
345	  ids: string[]
346	): Promise<{ suspended: number }> {
347	  const admin = await requireAdmin();
348	  const unique = [...new Set((ids ?? []).filter(Boolean))]
349	    .filter((id) => id !== admin.id)
350	    .slice(0, 500);
351	  if (unique.length === 0) return { suspended: 0 };
352	
353	  const res = await db.user.updateMany({
354	    where: { id: { in: unique }, role: { not: "ADMIN" } },
355	    data: { suspended: true },
356	  });
357	
358	  await audit(admin.id, "clients.bulk_suspend", `${res.count} suspended`);
359	  revalidatePath("/admin/users");
